import React, { useEffect, useMemo, useRef, useState } from "react";
import { Camera, Download, Layers3, Search, X } from "lucide-react";
import { recordDirectorVideo } from "./record-video";
import DirectorTimeline from "./DirectorTimeline";
import { sampleCameraMotion } from "./DirectorStage.motion";
import DirectorStageCanvas from "./DirectorStageCanvas";
import { DEFAULT_COMPOSITION } from "./DirectorStage.constants";
import { EnvironmentInspector, SelectionInspector } from "./DirectorStage.inspectors";
import type { SceneItem, ToolMenu } from "./DirectorStage.sceneTypes";
import { BottomTools, ViewportToolbar } from "./DirectorStage.toolbars";
import { downloadText, parseSceneSeed, ratioToNumber, type AspectRatio } from "./DirectorStage.utils";
import SceneTree from "./SceneTree";
import { useDirectorStage } from "./hooks/useDirectorStage";
import type {
  DirectorCamera,
  DirectorCharacter,
  DirectorPropType,
  DirectorStageProps,
  DirectorTransformMode,
  ParsedSceneSeed,
} from "./DirectorStage.types";
import "./DirectorStage.css";

const SAMPLE_SEED: ParsedSceneSeed = DEFAULT_COMPOSITION;

export default function DirectorStage({
  className,
  style,
  initialComposition,
  storageKey = "media-rig-director-stage-dark-v3",
  onCompositionChange,
  onCapture,
  onClose,
}: DirectorStageProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { state, dispatch } = useDirectorStage(initialComposition, storageKey);
  const viewRef = useRef<Pick<DirectorCamera, "position" | "lookAt" | "fov"> | null>(null);
  const uploadUrls = useRef<string[]>([]);
  const exportController = useRef<AbortController | null>(null);
  const [exporting, setExporting] = useState(false);
  useEffect(() => () => exportController.current?.abort(), []);
  const [timelineOpen, setTimelineOpen] = useState(false);
  const [motionTime, setMotionTime] = useState(0);
  const [motionPlaying, setMotionPlaying] = useState(false);
  const motions = state.composition.cameraMotions ?? [];
  const motionDuration = Math.max(6, ...motions.map((motion) => motion.start + motion.duration));
  useEffect(() => {
    if (!motionPlaying) return;
    let frame = 0;
    let previous = performance.now();
    const tick = (now: number) => {
      const delta = (now - previous) / 1000; previous = now;
      setMotionTime((time) => Math.min(motionDuration, time + delta));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [motionPlaying, motionDuration]);
  useEffect(() => { if (motionTime >= motionDuration) setMotionPlaying(false); }, [motionTime, motionDuration]);
  const currentMotion = timelineOpen ? [...motions].reverse().find((motion) => motionTime >= motion.start && motionTime <= motion.start + motion.duration) : undefined;
  const previewComposition = currentMotion ? { ...state.composition, cameras: state.composition.cameras.map((camera) => camera.id === currentMotion.cameraId ? sampleCameraMotion(currentMotion, motionTime) : camera) } : state.composition;
  const [query, setQuery] = useState("");
  const [shots, setShots] = useState<Array<{ url: string; label: string }>>([]);
  const [status, setStatus] = useState("");
  useEffect(() => () => uploadUrls.current.forEach((url) => URL.revokeObjectURL(url)), []);
  const [openMenu, setOpenMenu] = useState<ToolMenu>(null);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>("Auto");
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [jsonDraft, setJsonDraft] = useState(() => JSON.stringify(SAMPLE_SEED, null, 2));
  const [jsonMessage, setJsonMessage] = useState("可粘贴角色、道具、机位 JSON");

  useEffect(() => {
    onCompositionChange?.(state.composition);
  }, [onCompositionChange, state.composition]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      const tag = target?.tagName;
      if (exporting) return;
      if (!rootRef.current?.contains(target) || target?.isContentEditable || event.ctrlKey || event.metaKey || event.altKey) return;
      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return;
      if (event.code === "Space" && timelineOpen && motions.length && !exporting) {
        event.preventDefault(); if (motionTime >= motionDuration) setMotionTime(0);
        setMotionPlaying((playing) => !playing); dispatch({ type: "setViewMode", mode: "camera" }); return;
      }
      if (event.key === "Delete" || event.key === "Backspace") { event.preventDefault(); dispatch({ type: "removeSelected" }); }
      if (event.key.toLowerCase() === "v") dispatch({ type: "setTransformMode", mode: "translate" });
      if (event.key.toLowerCase() === "r") dispatch({ type: "setTransformMode", mode: "rotate" });
      if (event.key.toLowerCase() === "f") dispatch({ type: "setTransformMode", mode: "scale" });
      if (event.key === "Escape") setOpenMenu(null);
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [dispatch, timelineOpen, motions.length, exporting, motionTime, motionDuration]);

  useEffect(() => {
    const updateFullscreen = () => setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", updateFullscreen);
    return () => document.removeEventListener("fullscreenchange", updateFullscreen);
  }, []);

  useEffect(() => {
    if (!openMenu) return;
    const dismiss = (event: PointerEvent) => {
      if (!(event.target instanceof Element) || !event.target.closest(".director-stage__bottom-tools")) setOpenMenu(null);
    };
    document.addEventListener("pointerdown", dismiss);
    return () => document.removeEventListener("pointerdown", dismiss);
  }, [openMenu]);

  const selectedItem = useMemo<SceneItem | null>(() => {
    if (!state.selection) return null;
    if (state.selection.kind === "character") {
      const item = state.composition.characters.find((character) => character.id === state.selection?.id);
      return item ? { kind: "character", item } : null;
    }
    if (state.selection.kind === "prop") {
      const item = state.composition.props.find((prop) => prop.id === state.selection?.id);
      return item ? { kind: "prop", item } : null;
    }
    const item = state.composition.cameras.find((camera) => camera.id === state.selection?.id);
    return item ? { kind: "camera", item } : null;
  }, [state.composition, state.selection]);

  const captureCanvas = async () => {
    if (!state.composition.cameras.length) return;
    setMotionPlaying(false);
    dispatch({ type: "setViewMode", mode: "camera", cameraId: currentMotion?.cameraId ?? state.activeCameraId });
    await new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));
    const canvas = rootRef.current?.querySelector<HTMLCanvasElement>(".director-stage__viewport canvas");
    if (!canvas) return;
    let dataUrl: string;
    try {
      const ratio = ratioToNumber(aspectRatio);
      const output = document.createElement("canvas");
      const width = ratio ? Math.min(canvas.width, canvas.height * ratio) : canvas.width;
      const height = ratio ? width / ratio : canvas.height;
      output.width = Math.round(width); output.height = Math.round(height);
      output.getContext("2d")?.drawImage(canvas, (canvas.width - width) / 2, (canvas.height - height) / 2, width, height, 0, 0, output.width, output.height);
      dataUrl = output.toDataURL("image/png");
    } catch { setStatus("截图失败，请检查导入模型的跨域资源"); return; }
    setShots((previous) => [{ url: dataUrl, label: `镜头 ${previous.length + 1} · ${aspectRatio}` }, ...previous].slice(0, 8));
    setStatus("截图已导出");
    onCapture?.(dataUrl);
    const anchor = document.createElement("a");
    anchor.download = "director-stage.png";
    anchor.href = dataUrl;
    anchor.click();
  };

  const exportVideo = async () => {
    if (!motions.length || exporting) return;
    const controller = new AbortController(); exportController.current = controller;
    setExporting(true); setMotionTime(0); setMotionPlaying(false);
    dispatch({ type: "setViewMode", mode: "camera" });
    try {
      await new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));
      const canvas = rootRef.current?.querySelector<HTMLCanvasElement>(".director-stage__viewport canvas");
      if (!canvas) throw new Error("画布未就绪");
      setMotionPlaying(true);
      const blob = await recordDirectorVideo(canvas, motionDuration, ratioToNumber(aspectRatio), controller.signal);
      const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `director-motion.${blob.type.includes("mp4") ? "mp4" : "webm"}`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); setStatus("运镜视频已导出");
    } catch (error) { setStatus(error instanceof Error ? error.message : "视频导出失败"); }
    finally { setExporting(false); setMotionPlaying(false); exportController.current = null; }
  };

  const importJson = () => {
    try {
      dispatch({ type: "importSeed", seed: parseSceneSeed(jsonDraft) });
      setJsonMessage("已导入场景 seed");
    } catch (error) {
      setJsonMessage(error instanceof Error ? error.message : "JSON 格式不正确");
    }
  };

  const addUploadedModel = (file: File | undefined) => {
    if (!file) return;
    if (!/\.glb$/i.test(file.name)) { setStatus("请选择包含贴图的 GLB 文件"); return; }
    const url = URL.createObjectURL(file);
    uploadUrls.current.push(url);
    dispatch({ type: "addCharacter", modelUrl: url, label: file.name.replace(/\.(glb|gltf)$/i, "") || "自定义角色" });
    setOpenMenu(null);
  };

  const setMode = (mode: DirectorTransformMode) => {
    dispatch({ type: "setTransformMode", mode });
    setOpenMenu(null);
  };

  const addCharacter = (bodyType: DirectorCharacter["bodyType"], label?: string) => {
    dispatch({ type: "addCharacter", bodyType, label });
    setOpenMenu(null);
  };

  const addCrowd = () => {
    const spacing = 0.72;
    for (let row = 0; row < 3; row += 1) {
      for (let col = 0; col < 3; col += 1) {
        dispatch({
          type: "addCharacter",
          bodyType: "mannequin",
          label: `群众 ${row * 3 + col + 1}`,
          position: { x: (col - 1) * spacing, y: 0, z: 0.8 + row * spacing },
        });
      }
    }
    setOpenMenu(null);
  };

  const addProp = (nextPropType: DirectorPropType, label?: string) => {
    dispatch({ type: "addProp", propType: nextPropType, label });
    setOpenMenu(null);
  };

  const addCamera = (camera?: Partial<DirectorCamera>) => {
    const focus = selectedItem?.kind === "character" || selectedItem?.kind === "prop" ? selectedItem.item.position : state.composition.characters[0]?.position;
    const offset = (value: DirectorCamera["position"]) => ({ x: value.x + (focus?.x ?? 0), y: value.y + (focus?.y ?? 0), z: value.z + (focus?.z ?? 0) });
    dispatch({ type: "addCamera", camera: camera?.label && camera.position && camera.lookAt ? { ...camera, position: offset(camera.position), lookAt: offset(camera.lookAt) } : camera });
    setOpenMenu(null);
  };

  const applyCurrentViewCamera = () => {
    addCamera(viewRef.current ?? undefined);
  };

  const toggleFullscreen = async () => {
    try {
      if (document.fullscreenElement) {
        await document.exitFullscreen();
      } else {
        await rootRef.current?.requestFullscreen();
      }
    } catch {
      // Browsers may reject fullscreen without a trusted user gesture.
    }
    setOpenMenu(null);
  };

  const aspectNumber = ratioToNumber(aspectRatio);
  const stageClassName = ["director-stage", isFullscreen ? "is-fullscreen" : "", className].filter(Boolean).join(" ");

  return (
    <div className={stageClassName} style={style} ref={rootRef} tabIndex={-1} onPointerDown={(event) => { if (!(event.target as HTMLElement).closest("button, input, select, textarea, a")) rootRef.current?.focus({ preventScroll: true }); }}>
      {exporting && <div className="director-stage__export-overlay" role="status"><span>正在导出运镜视频 · {Math.round(motionTime / motionDuration * 100)}%</span><button type="button" onClick={() => exportController.current?.abort()}>取消</button></div>}
      <header className="director-stage__topbar">
        <div className="director-stage__brand">
          <h1>3D导演台</h1>
        </div>
        <div className="director-stage__top-actions">
          <span className="director-stage__status" role="status">{status}</span>
          {onClose && <button type="button" aria-label="关闭 3D 导演台" title="关闭 3D 导演台" onClick={onClose}><X size={16} /></button>}
        </div>
      </header>

      <div className="director-stage__body">
        <aside className="director-stage__rail" aria-label="场景层级">
          <section>
            <div className="director-stage__hierarchy-heading"><Layers3 size={18} /><div><strong>场景层级</strong><small>{state.composition.characters.length + state.composition.cameras.length + state.composition.props.length} 个对象</small></div></div>
            <label className="director-stage__search">
              <Search size={16} />
              <input aria-label="搜索场景对象" placeholder="搜索场景对象…" value={query} onChange={(event) => setQuery(event.target.value)} />
            </label>
            <input
              ref={fileInputRef}
              type="file"
              accept=".glb,model/gltf-binary"
              hidden
              onChange={(event) => { addUploadedModel(event.target.files?.[0]); event.target.value = ""; }}
            />
          </section>

          <section>
            <SceneTree
              composition={state.composition}
              query={query}
              selection={state.selection}
              onSelect={(selection) => dispatch({ type: "select", selection })}
              onDuplicate={(selection) => dispatch({ type: "duplicateItem", selection })}
              onRemove={(selection) => dispatch({ type: "removeItem", selection })}
              activeCameraId={currentMotion?.cameraId ?? state.activeCameraId}
              onRename={(selection, label) => {
                if (selection.kind === "character") dispatch({ type: "updateCharacter", id: selection.id, patch: { label } });
                else if (selection.kind === "prop") dispatch({ type: "updateProp", id: selection.id, patch: { label } });
                else dispatch({ type: "updateCamera", id: selection.id, patch: { label } });
              }}
              onToggleVisible={(selection, visible) => dispatch({ type: "setItemVisible", selection, visible })}
            />
          </section>
        </aside>

        <div className="director-stage__center">
        <main className="director-stage__viewport">
          <ViewportToolbar
            transformMode={state.transformMode}
            viewMode={state.viewMode}
            onRemoveSelected={() => dispatch({ type: "removeSelected" })}
            onSetTransformMode={(mode) => dispatch({ type: "setTransformMode", mode })}
            onSetViewMode={(mode) => dispatch({ type: "setViewMode", mode })}
          />

          <DirectorStageCanvas
            motionPath={currentMotion?.points}
            onViewChange={(camera) => { viewRef.current = camera; }}
            composition={previewComposition}
            selection={state.viewMode === "camera" ? null : state.selection}
            transformMode={state.transformMode}
            viewMode={state.viewMode}
            activeCameraId={currentMotion?.cameraId ?? state.activeCameraId}
            onSelect={(selection) => dispatch({ type: "select", selection })}
            onTransform={(transform) => dispatch({ type: "transformSelected", transform })}
          />

          {aspectNumber ? (
            <div className="director-stage__aspect-frame" style={{ aspectRatio: aspectNumber, width: `min(100%, calc((100cqh) * ${aspectNumber}))`, maxHeight: "100%", top: "50%" }} aria-hidden="true" />
          ) : null}

          <div className="director-stage__viewport-info"><span>{state.viewMode === "camera" ? "机位预览" : "场景视图"}</span><span>V 移动 · R 旋转 · F 缩放 · Delete 删除</span></div>
          <BottomTools
            timelineOpen={timelineOpen}
            onToggleTimeline={() => { setTimelineOpen(!timelineOpen); setMotionPlaying(false); setOpenMenu(null); }}
            onCapture={captureCanvas}
            aspectRatio={aspectRatio}
            isFullscreen={isFullscreen}
            openMenu={openMenu}
            transformMode={state.transformMode}
            onAddCamera={addCamera}
            onAddCharacter={addCharacter}
            onAddCrowd={addCrowd}
            onAddProp={addProp}
            onApplyCurrentViewCamera={applyCurrentViewCamera}
            onClickUpload={() => fileInputRef.current?.click()}
            onSetAspectRatio={setAspectRatio}
            onSetMode={setMode}
            onSetOpenMenu={setOpenMenu}
            onToggleFullscreen={toggleFullscreen}
          />
        </main>
        {timelineOpen && <DirectorTimeline cameras={state.composition.cameras} activeCameraId={state.activeCameraId} motions={motions} time={motionTime} playing={motionPlaying} onTime={setMotionTime} onPlaying={(playing) => { setMotionPlaying(playing); if (playing) dispatch({ type: "setViewMode", mode: "camera" }); }} onChange={(next) => dispatch({ type: "setCameraMotions", motions: next })} onClose={() => { setTimelineOpen(false); setMotionPlaying(false); }} onExport={exportVideo} />}
        </div>

        <aside className="director-stage__inspector" aria-label="属性检查器">
          <section><div className="director-stage__panel-title">机位切换</div><div className="director-stage__camera-list">{state.composition.cameras.map((camera) => <button type="button" key={camera.id} className={state.activeCameraId === camera.id ? "is-active" : ""} onClick={() => { dispatch({ type: "select", selection: { kind: "camera", id: camera.id } }); dispatch({ type: "setViewMode", mode: "camera", cameraId: camera.id }); }}><Camera size={14} />{camera.label}</button>)}</div></section>
          <SelectionInspector
            composition={state.composition}
            selectedItem={selectedItem}
            onPatchCharacter={(id, patch) => dispatch({ type: "updateCharacter", id, patch })}
            onPatchProp={(id, patch) => dispatch({ type: "updateProp", id, patch })}
            onPatchCamera={(id, patch) => dispatch({ type: "updateCamera", id, patch })}
          />
          <EnvironmentInspector
            environment={state.composition.environment}
            onPatch={(patch) => dispatch({ type: "updateEnvironment", patch })}
          />

          <section>
            <details><summary className="director-stage__panel-title">场景 JSON</summary>
            <textarea value={jsonDraft} spellCheck={false} onChange={(event) => setJsonDraft(event.target.value)} />
            <div className="director-stage__json-actions">
              <button type="button" onClick={() => downloadText("director-composition.json", JSON.stringify(state.composition, null, 2))}><Download size={14} />导出</button>
              <button type="button" onClick={importJson}>导入</button>
              <button type="button" onClick={() => setJsonDraft(JSON.stringify(state.composition, null, 2))}>当前</button>
            </div>
            <p className="director-stage__hint" role="status">{jsonMessage}</p></details>
          </section>
          {shots.length > 0 && <section><div className="director-stage__panel-title">镜头记录</div><div className="director-stage__shots">{shots.map((shot, index) => <a key={index} href={shot.url} download={`shot-${index + 1}.png`}><img src={shot.url} alt={shot.label} /><span>{shot.label}</span></a>)}</div></section>}
        </aside>
      </div>
    </div>
  );
}

.director-stage {
  --stage-bg: #121212;
  --stage-panel: #171717;
  --stage-panel-2: #1d1d1d;
  --stage-line: rgba(255, 255, 255, 0.08);
  --stage-line-strong: rgba(255, 255, 255, 0.14);
  --stage-text: #f4f4f4;
  --stage-muted: #969696;
  --stage-dim: #666666;
  --stage-gold: #ffffff;
  --stage-cyan: #8ca9ff;
  --stage-green: #75b985;
  display: grid;
  grid-template-rows: 54px minmax(0, 1fr);
  width: 100%;
  height: 100vh;
  min-height: 620px;
  overflow: hidden;
  background: var(--stage-bg);
  color: var(--stage-text);
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
}

.director-stage *,
.director-stage *::before,
.director-stage *::after {
  box-sizing: border-box;
}

.director-stage button,
.director-stage input,
.director-stage select,
.director-stage textarea {
  font: inherit;
  letter-spacing: 0;
}

.director-stage button {
  cursor: pointer;
}

.director-stage__topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-bottom: 1px solid var(--stage-line);
  background: #151515;
  padding: 0 18px;
}

.director-stage__brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.director-stage__brand-mark {
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  border-radius: 2px;
  border: 1px solid var(--stage-line-strong);
  background: rgba(255, 255, 255, 0.08);
  color: var(--stage-text);
  font-size: 14px;
  line-height: 1;
}

.director-stage h1 {
  margin: 0;
  font-size: 15px;
  font-weight: 760;
  line-height: 1.15;
}

.director-stage__top-actions,
.director-stage__json-actions,
.director-stage__prop-add {
  display: flex;
  align-items: center;
  gap: 8px;
}

.director-stage__top-actions button,
.director-stage__prop-add button,
.director-stage__json-actions button,
.director-stage__pose-grid button,
.director-stage__asset-grid button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--stage-line);
  border-radius: 8px;
  background: var(--stage-panel-2);
  color: var(--stage-text);
  font-size: 13px;
  font-weight: 690;
  line-height: 1;
  padding: 0 11px;
}

.director-stage__top-actions button:hover,
.director-stage__prop-add button:hover,
.director-stage__json-actions button:hover,
.director-stage__pose-grid button:hover,
.director-stage__asset-grid button:hover,
.director-stage__tree-item:hover,
.director-stage__segmented button:hover,
.director-stage__icon-button:hover {
  border-color: rgba(255, 255, 255, 0.24);
  color: #ffffff;
}

.director-stage__body {
  display: grid;
  min-height: 0;
  grid-template-columns: 280px minmax(520px, 1fr) 340px;
}

.director-stage.is-fullscreen .director-stage__body {
  grid-template-columns: minmax(0, 1fr);
}

.director-stage.is-fullscreen .director-stage__rail,
.director-stage.is-fullscreen .director-stage__inspector {
  display: none;
}

.director-stage__rail,
.director-stage__inspector {
  min-height: 0;
  overflow-y: auto;
  background: var(--stage-panel);
  padding: 16px;
}

.director-stage__rail {
  border-right: 1px solid var(--stage-line);
}

.director-stage__inspector {
  border-left: 1px solid var(--stage-line);
}

.director-stage__rail section + section,
.director-stage__inspector section + section {
  border-top: 1px solid var(--stage-line);
  margin-top: 16px;
  padding-top: 16px;
}

.director-stage__panel-title,
.director-stage__section-title,
.director-stage__tree-title {
  color: var(--stage-text);
  font-size: 14px;
  font-weight: 780;
  line-height: 1.2;
  margin-bottom: 10px;
}

.director-stage__tree-title {
  display: flex;
  justify-content: space-between;
  color: var(--stage-muted);
  font-size: 13px;
  font-weight: 620;
  margin: 18px 4px 8px;
}

.director-stage__search {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  height: 42px;
  border: 1px solid var(--stage-line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
  color: #777777;
  padding: 0 12px;
  margin: 14px 0 16px;
}

.director-stage__search input {
  border: 0 !important;
  box-shadow: none !important;
  height: 38px !important;
  padding: 0 !important;
  background: transparent !important;
}

.director-stage__asset-grid {
  display: none;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.director-stage__asset-grid button {
  min-width: 0;
  flex-direction: column;
  height: 62px;
  padding: 8px;
}

.director-stage__asset-grid span {
  overflow: hidden;
  max-width: 100%;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.director-stage__prop-add {
  display: none;
  margin-top: 10px;
}

.director-stage select,
.director-stage input:not([type="range"]):not([type="checkbox"]),
.director-stage textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--stage-line);
  border-radius: 8px;
  background: #1b1b1b;
  color: var(--stage-text);
  outline: none;
}

.director-stage select,
.director-stage input:not([type="range"]):not([type="checkbox"]) {
  height: 34px;
  padding: 0 10px;
}

.director-stage input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--stage-gold);
}

.director-stage input[type="color"] {
  min-width: 52px;
  padding: 4px;
}

.director-stage select:focus,
.director-stage input:focus,
.director-stage textarea:focus {
  border-color: rgba(255, 255, 255, 0.34);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.08);
}

.director-stage__tree {
  display: block;
}

.director-stage__tree-item {
  display: grid;
  width: 100%;
  grid-template-columns: 22px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: #8b8b8b;
  min-height: 35px;
  padding: 0 7px 0 10px;
  text-align: left;
}

.director-stage__tree-item span:nth-child(2) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.director-stage__tree-item.is-active {
  border-color: var(--stage-line);
  background: rgba(255, 255, 255, 0.06);
  color: #f4f4f4;
  font-weight: 760;
}

.director-stage__tree-actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  justify-self: end;
  opacity: 0;
  pointer-events: none;
  transition: opacity 120ms ease;
}

.director-stage__tree-item:hover .director-stage__tree-actions,
.director-stage__tree-item.is-active .director-stage__tree-actions,
.director-stage__tree-actions:focus-within {
  opacity: 1;
  pointer-events: auto;
}

.director-stage__tree-actions button {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #777777;
  padding: 0;
}

.director-stage__tree-actions button:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}

.director-stage__tree-icon {
  display: grid;
  place-items: center;
  color: #777777;
  font-size: 16px;
}

.director-stage__tree-icon.is-character {
  color: #4a7cff;
}

.director-stage__viewport {
  position: relative;
  min-width: 0;
  min-height: 0;
  background: #141414;
}

.director-stage__viewport canvas {
  display: block;
  background: #141414;
}

.director-stage__camera-monitor {
  overflow: hidden;
  border: 1px solid var(--stage-line-strong);
  border-radius: 8px;
  background: #111111;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.28);
  margin-bottom: 16px;
}

.director-stage__camera-monitor-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  height: 30px;
  border-bottom: 1px solid var(--stage-line);
  color: #8a8a8a;
  font-size: 12px;
  font-weight: 720;
  line-height: 1;
  padding: 0 10px;
}

.director-stage__camera-monitor-head span {
  overflow: hidden;
  min-width: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.director-stage__camera-monitor-head strong {
  flex: 0 0 auto;
  color: #d8d8d8;
  font-weight: 800;
}

.director-stage__camera-monitor-canvas {
  aspect-ratio: 1 / 0.95;
  width: 100%;
  background: #111111;
}

.director-stage__camera-monitor-canvas canvas {
  display: block;
}

.director-stage__viewport-toolbar {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  height: 66px;
  border-bottom: 1px solid var(--stage-line);
  background: rgba(18, 18, 18, 0.9);
  backdrop-filter: blur(14px);
  pointer-events: none;
}

.director-stage__segmented,
.director-stage__tools {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid var(--stage-line);
  border-radius: 9px;
  background: rgba(28, 28, 28, 0.94);
  padding: 3px;
  pointer-events: auto;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.24);
}

.director-stage__tools {
  position: absolute;
  right: 20px;
}

.director-stage__segmented button {
  min-width: 96px;
  height: 34px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: #777777;
  font-size: 15px;
  font-weight: 720;
}

.director-stage__segmented button.is-active,
.director-stage__icon-button.is-active {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.1);
  color: white;
}

.director-stage__icon-button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: #777777;
}

.director-stage__field {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  color: #8a8a8a;
  font-size: 13px;
  margin-bottom: 12px;
}

.director-stage__field > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.director-stage__vector {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: center;
  gap: 7px;
  color: #8a8a8a;
  font-size: 13px;
  margin-bottom: 12px;
}

.director-stage__vector > span {
  grid-column: 1 / -1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.director-stage__slider {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr) 42px;
  align-items: center;
  gap: 8px;
  color: #8a8a8a;
  font-size: 13px;
  margin-bottom: 10px;
}

.director-stage__slider input {
  width: 100%;
  accent-color: var(--stage-gold);
}

.director-stage__slider output {
  color: var(--stage-text);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.director-stage__swatches {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
  margin: 2px 0 12px;
}

.director-stage__swatches button {
  width: 100%;
  aspect-ratio: 1;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
}

.director-stage__swatches button.is-active {
  outline: 2px solid white;
  outline-offset: 2px;
}

.director-stage__pose-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  margin: 0 0 12px;
}

.director-stage__pose-grid button {
  min-width: 0;
  padding: 0 6px;
  font-size: 12px;
}

.director-stage textarea {
  min-height: 156px;
  resize: vertical;
  padding: 10px;
  color: #c7c7c7;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: 12px;
  line-height: 1.45;
}

.director-stage__select-like {
  display: flex;
  width: 100%;
  height: 40px;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--stage-line);
  border-radius: 8px;
  background: #1b1b1b;
  color: var(--stage-text);
  font-weight: 720;
  padding: 0 12px;
}

.director-stage__bottom-tools {
  position: absolute;
  left: 50%;
  bottom: 28px;
  z-index: 3;
  display: inline-flex;
  gap: 12px;
  transform: translateX(-50%);
  border: 1px solid var(--stage-line);
  border-radius: 12px;
  background: rgba(28, 28, 28, 0.94);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.34);
  backdrop-filter: blur(14px);
  padding: 10px 16px;
}

.director-stage__tool-slot {
  position: relative;
}

.director-stage__tool-menu {
  position: absolute;
  bottom: calc(100% + 14px);
  left: 50%;
  z-index: 8;
  width: 226px;
  max-height: min(430px, calc(100vh - 220px));
  overflow-y: auto;
  transform: translateX(-50%);
  border: 1px solid var(--stage-line-strong);
  border-radius: 13px;
  background: rgba(25, 25, 25, 0.98);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.42);
  padding: 12px;
}

.director-stage__tool-menu.is-wide {
  width: 452px;
}

.director-stage__tool-menu::-webkit-scrollbar {
  width: 4px;
}

.director-stage__tool-menu::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: #444444;
}

.director-stage__tool-menu-item {
  display: grid;
  width: 100%;
  grid-template-columns: 28px minmax(0, 1fr) 24px;
  align-items: center;
  gap: 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #969696;
  font-size: 16px;
  font-weight: 620;
  min-height: 36px;
  padding: 0 8px;
  text-align: left;
}

.director-stage__tool-menu-item:hover,
.director-stage__tool-menu-item.is-active {
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}

.director-stage__tool-menu-item kbd {
  color: #6f6f6f;
  font-size: 14px;
  font-weight: 620;
  text-align: right;
}

.director-stage__tool-menu-mark {
  display: grid;
  place-items: center;
  color: #858585;
  font-size: 17px;
}

.director-stage__tool-menu-separator {
  height: 1px;
  background: var(--stage-line);
  margin: 10px 0;
}

.director-stage__tool-menu-heading {
  color: #707070;
  font-size: 12px;
  font-weight: 620;
  line-height: 1;
  padding: 4px 8px 8px;
}

.director-stage__aspect-title {
  color: #a0a0a0;
  font-size: 16px;
  font-weight: 640;
  margin: 2px 4px 12px;
}

.director-stage__aspect-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.director-stage__aspect-option {
  display: grid;
  height: 94px;
  place-items: center;
  gap: 8px;
  border: 1px solid var(--stage-line);
  background: #1b1b1b;
  color: #8c8c8c;
  font-size: 15px;
}

.director-stage__aspect-option.is-active {
  border-color: rgba(255, 255, 255, 0.42);
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}

.director-stage__aspect-icon {
  display: block;
  width: 32px;
  height: 22px;
  border: 3px solid #777777;
}

.director-stage__aspect-icon.is-auto {
  width: 28px;
  height: 28px;
  border-style: dashed;
}

.director-stage__aspect-icon.is-21-9 {
  width: 40px;
  height: 14px;
}

.director-stage__aspect-icon.is-16-9 {
  width: 36px;
  height: 18px;
}

.director-stage__aspect-icon.is-4-3 {
  width: 30px;
  height: 24px;
}

.director-stage__aspect-icon.is-1-1 {
  width: 28px;
  height: 28px;
}

.director-stage__aspect-icon.is-3-4 {
  width: 22px;
  height: 30px;
}

.director-stage__aspect-icon.is-9-16 {
  width: 18px;
  height: 34px;
}

.director-stage__aspect-frame {
  position: absolute;
  left: 50%;
  top: calc(50% + 22px);
  z-index: 2;
  width: min(78%, 900px);
  max-height: calc(100% - 160px);
  transform: translate(-50%, -50%);
  border: 1px solid rgba(255, 255, 255, 0.48);
  box-shadow: 0 0 0 9999px rgba(0, 0, 0, 0.32);
  pointer-events: none;
}

.director-stage__fullscreen-glyph {
  font-size: 18px;
  font-weight: 760;
  line-height: 1;
}

.director-stage__top-actions button {
  width: 34px;
  min-height: 34px;
  padding: 0;
  border-color: transparent;
  background: transparent;
  color: #808080;
}

.director-stage__app-dots {
  color: #666666;
  font-size: 22px;
  letter-spacing: 2px;
  line-height: 1;
  writing-mode: vertical-rl;
}

.director-stage__json-actions {
  justify-content: flex-end;
  margin-top: 8px;
}

.director-stage__empty,
.director-stage__hint {
  color: var(--stage-dim);
  font-size: 12px;
  line-height: 1.5;
  margin: 8px 0 0;
}

@media (max-width: 1180px) {
  .director-stage {
    min-height: 760px;
  }

  .director-stage__body {
    grid-template-columns: 218px minmax(360px, 1fr);
    grid-template-rows: minmax(0, 1fr) 260px;
  }

  .director-stage__inspector {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 14px;
    border-left: 0;
    border-top: 1px solid var(--stage-line);
  }

  .director-stage__inspector section + section {
    border-top: 0;
    margin-top: 0;
    padding-top: 0;
  }
}

@media (max-width: 760px) {
  .director-stage {
    grid-template-rows: auto minmax(0, 1fr);
    min-height: 900px;
  }

  .director-stage__topbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .director-stage__body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(420px, 1fr) auto;
  }

  .director-stage__rail,
  .director-stage__inspector {
    border: 0;
    border-top: 1px solid var(--stage-line);
  }

  .director-stage__rail {
    order: 2;
  }

  .director-stage__viewport {
    order: 1;
  }

  .director-stage__inspector {
    order: 3;
    display: block;
  }

  .director-stage__inspector section + section {
    border-top: 1px solid var(--stage-line);
    margin-top: 16px;
    padding-top: 16px;
  }

  .director-stage__viewport-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

}

/* Compact neutral panels, following the tamen director desk. */
.director-stage { --stage-panel: #181818; --stage-bg: #080808; color-scheme: dark; }
.director-stage__body { grid-template-columns: 240px minmax(0, 1fr) 300px; }
.director-stage__viewport { container-type: size; }
.director-stage__camera-list { display: flex; gap: 6px; flex-wrap: wrap; }
.director-stage__camera-list button { display: inline-flex; align-items: center; gap: 6px; padding: 7px 9px; background: #242424; border: 1px solid var(--stage-line); border-radius: 6px; color: #a1a1a1; font-size: 12px; }
.director-stage__camera-list button.is-active { color: #aac8ff; background: #4f8ef71a; border-color: #4f8ef766; }
.director-stage__status { color: #999; font-size: 11px; }
.director-stage__viewport-info { position: absolute; bottom: 8px; left: 14px; right: 14px; display: flex; justify-content: space-between; gap: 10px; color: #969696; font-size: 10px; pointer-events: none; z-index: 2; }
.director-stage__shots { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.director-stage__shots a { overflow: hidden; border: 1px solid var(--stage-line); border-radius: 6px; color: #aaa; text-decoration: none; font-size: 11px; }
.director-stage__shots img { display: block; width: 100%; aspect-ratio: 16 / 9; object-fit: contain; background: #080808; }
.director-stage__shots span { display: block; padding: 7px; }
.director-stage summary { cursor: pointer; }
.director-stage button:focus-visible, .director-stage a:focus-visible, .director-stage summary:focus-visible { outline: 2px solid #4f8ef7; outline-offset: 2px; }
.director-stage__tree-item.is-active { background: #4f8ef71a; }
.director-stage__segmented button { min-width: 62px; font-size: 12px; }
.director-stage__viewport-toolbar { justify-content: flex-start; padding-left: 12px; height: 54px; }
.director-stage__tools { right: 12px; }
.director-stage__pose-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.director-stage__camera-monitor-canvas { aspect-ratio: 16 / 9; }
@media (max-width: 1180px) {
  .director-stage__body { grid-template-columns: 200px minmax(0, 1fr); }
  .director-stage__inspector { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 760px) {
  .director-stage__body { grid-template-columns: minmax(0, 1fr); }
  .director-stage__topbar { flex-direction: row; align-items: center; min-height: 48px; }
  .director-stage__viewport-info span:last-child { display: none; }
  .director-stage__bottom-tools { gap: 4px; padding: 8px; bottom: 28px; }
  .director-stage__tool-menu.is-wide { width: min(340px, 90vw); }
  .director-stage__viewport-toolbar { flex-direction: row; align-items: center; }
  .director-stage__tools { position: static; }
}
.director-stage.is-fullscreen .director-stage__body { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); }
.director-stage__viewport-toolbar { height: auto; min-height: 54px; flex-wrap: wrap; gap: 8px; padding: 8px 12px; }
.director-stage__tools { position: static; margin-left: auto; }
.director-stage__segmented button { min-width: 44px; }
.director-stage__tree-item { grid-template-columns: 20px minmax(0, 1fr); gap: 6px; padding: 7px 8px; }
.director-stage__tree-actions { grid-column: 2; display: none; }
.director-stage__tree-item:hover .director-stage__tree-actions,
.director-stage__tree-item:focus-within .director-stage__tree-actions,
.director-stage__tree-item.is-active .director-stage__tree-actions { display: inline-flex; opacity: 1; pointer-events: auto; }

.director-stage * {
  scrollbar-width: thin;
  scrollbar-color: #414141 transparent;
}
.director-stage *::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
.director-stage *::-webkit-scrollbar-track {
  background: transparent;
}
.director-stage *::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: #414141;
}
.director-stage *::-webkit-scrollbar-thumb:hover {
  background: #606060;
}
.director-stage *::-webkit-scrollbar-corner {
  background: transparent;
}

.director-stage__body { grid-template-columns: 250px minmax(0, 1fr) 310px; }
.director-stage__rail { padding: 12px; display: flex; flex-direction: column; overflow: hidden; }
.director-stage__rail > section:last-child { flex: 1; min-height: 0; overflow: auto; border: 0; margin-top: 0; padding-top: 0; }
.director-stage__hierarchy-heading { display: flex; align-items: center; gap: 10px; padding: 0 4px; font-size: 14px; }
.director-stage__hierarchy-heading > svg { color: #b8b8b8; }
.director-stage__hierarchy-heading small { display: block; color: #777; font-size: 10px; margin-top: 3px; }
.director-stage__tree-title { display: flex; align-items: center; gap: 6px; width: 100%; padding: 8px 6px; border: 0; border-radius: 6px; background: transparent; text-align: left; font-size: 12px; font-weight: 500; margin: 4px 0; }
.director-stage__tree-title:hover { background: #ffffff0a; }
.director-stage__tree-title > span:last-child { margin-left: auto; color: #777; font-size: 10px; }
.director-stage__tree-branch { margin: 2px 0 8px 16px; padding-left: 8px; border-left: 1px solid #ffffff14; }
.director-stage__tree-branch > .director-stage__empty { padding: 6px 8px; margin: 0; font-size: 10px; }
.director-stage__inspector { background: #202020; }
.director-stage.is-fullscreen .director-stage__rail,
.director-stage.is-fullscreen .director-stage__inspector { display: block; }
.director-stage.is-fullscreen .director-stage__body { grid-template-columns: 250px minmax(0, 1fr) 310px; }
@media (max-width: 1000px) {
  .director-stage__body, .director-stage.is-fullscreen .director-stage__body { grid-template-columns: 190px minmax(0, 1fr) 260px; grid-template-rows: minmax(0, 1fr); }
  .director-stage__inspector { grid-column: auto; display: block; }
}
@media (max-width: 760px) {
  .director-stage__body, .director-stage.is-fullscreen .director-stage__body { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(300px, 1fr) 220px; }
  .director-stage__rail { display: none; }
  .director-stage__viewport { grid-row: 1; }
  .director-stage__inspector { grid-row: 2; }
}
.director-stage__inspector-tabs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; border-bottom: 1px solid #ffffff14; margin: 0 0 16px; padding: 0 0 8px; }
.director-stage__inspector-tabs button { height: 32px; border: 0; border-radius: 6px; background: transparent; color: #8f8f8f; font-size: 12px; }
.director-stage__inspector-tabs button[aria-pressed="true"] { background: #ffffff12; color: white; }
.director-stage__bottom-tools { gap: 4px; padding: 6px; bottom: 24px; border-radius: 16px; background: #202020f2; }
.director-stage__bottom-tools > .director-stage__tool-slot > button { width: 40px; height: 40px; border-radius: 12px; }
.director-stage__viewport-toolbar { border-bottom: 0; background: transparent; backdrop-filter: none; }
.director-stage__viewport-toolbar > .director-stage__segmented { margin: 0 auto; }
.director-stage__viewport-toolbar > .director-stage__tools { position: absolute; right: 12px; top: 60px; flex-direction: column; }
.director-stage__tool-menu-item { font-size: 12px; min-height: 32px; }
.director-stage__tool-menu { width: 190px; border-radius: 8px; padding: 6px; }

/* Tamen workspace controls and timeline. */
.director-stage__center { display: flex; flex-direction: column; min-width: 0; min-height: 0; overflow: hidden; }
.director-stage__center > .director-stage__viewport { flex: 1; min-height: 180px; }
.director-stage__viewport-toolbar { justify-content: center; padding: 8px; }
.director-stage__viewport-toolbar > .director-stage__segmented { margin: 0; border-radius: 12px; background: #252525f2; padding: 2px; }
.director-stage__segmented button { min-width: 80px; height: 32px; font-size: 12px; font-weight: 500; }
.director-stage__bottom-tools { bottom: 12px; gap: 4px; padding: 6px; }
