}

import { useState } from "react";
import { ChevronDown, ChevronRight, Camera, UserRound, Box, Copy, Eye, EyeOff, Pencil, Trash2 } from "lucide-react";
import { selectionKey } from "./DirectorStage.utils";
import type { SceneItem } from "./DirectorStage.sceneTypes";
import type { DirectorComposition, DirectorSelection } from "./DirectorStage.types";

export default function SceneTree({
  composition,
  query = "",
  selection,
  onSelect,
  onDuplicate,
  onRemove,
  onRename,
  activeCameraId,
  onToggleVisible,
}: {
  composition: DirectorComposition;
  query?: string;
  selection: DirectorSelection;
  onSelect: (selection: DirectorSelection) => void;
  onDuplicate: (selection: Exclude<DirectorSelection, null>) => void;
  onRemove: (selection: Exclude<DirectorSelection, null>) => void;
  activeCameraId: string | null;
  onRename: (selection: Exclude<DirectorSelection, null>, label: string) => void;
  onToggleVisible: (selection: Exclude<DirectorSelection, null>, visible: boolean) => void;
}) {
  const [renaming, setRenaming] = useState<string | null>(null);
  const [draftName, setDraftName] = useState("");
  const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
  const groups: Array<{ title: string; items: SceneItem[] }> = [
    { title: "角色", items: composition.characters.map((item) => ({ kind: "character", item })) },
    { title: "摄像机", items: composition.cameras.map((item) => ({ kind: "camera", item })) },
    { title: "道具", items: composition.props.map((item) => ({ kind: "prop", item })) },
  ];

  return (
    <div className="director-stage__tree">
      {groups.map((group) => {
        const items = group.items.filter(({ item }) => item.label.toLowerCase().includes(query.trim().toLowerCase()));
        const open = Boolean(query) || !collapsed[group.title];
        return <div key={group.title}>
          <button type="button" className="director-stage__tree-title" aria-expanded={open} onClick={() => setCollapsed((previous) => ({ ...previous, [group.title]: open }))}>
            {open ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
            {group.title === "角色" ? <UserRound size={14} /> : group.title === "摄像机" ? <Camera size={14} /> : <Box size={14} />}
            <span>{group.title}</span><span>{items.length}</span>
          </button>
          {open && <div className="director-stage__tree-branch">
          {items.length === 0 && <p className="director-stage__empty">{query ? "没有匹配的对象" : "暂无对象"}</p>}
          {items.map(({ kind, item }) => {
            const selected = selectionKey(selection) === `${kind}:${item.id}`;
            const itemSelection = { kind, id: item.id } as Exclude<DirectorSelection, null>;
            return (
              <div
                key={item.id}
                className={selected ? "director-stage__tree-item is-active" : "director-stage__tree-item"}
              >
                {renaming === item.id ? <input autoFocus aria-label={`重命名 ${item.label}`} value={draftName} onFocus={(event) => event.target.select()} onChange={(event) => setDraftName(event.target.value)} onBlur={() => { if (draftName.trim()) onRename(itemSelection, draftName.trim()); setRenaming(null); }} onKeyDown={(event) => { if (event.key === "Enter") event.currentTarget.blur(); if (event.key === "Escape") { event.stopPropagation(); setRenaming(null); } }} /> : <button type="button" className="director-stage__tree-select" onClick={() => onSelect(itemSelection)} style={{ opacity: item.visible ? 1 : 0.4 }}>
                  {kind === "camera" ? <Camera size={14} /> : kind === "character" ? <UserRound size={14} /> : <Box size={14} />}
                  <span>{item.label}</span>{kind === "camera" && activeCameraId === item.id && <i className="director-stage__active-camera" aria-label="当前机位" />}
                </button>}
                <div className="director-stage__tree-actions">
                  <button
                    type="button"
                    title="复制"
                    aria-label={`复制 ${item.label}`}
                    onClick={(event) => {
                      event.stopPropagation();
                      onDuplicate(itemSelection);
                    }}
                  >
                    <Copy size={14} />
                  </button>
                  <button type="button" title="重命名" aria-label={`重命名 ${item.label}`} onClick={() => { setDraftName(item.label); setRenaming(item.id); }}><Pencil size={14} /></button>
                  <button
                    type="button"
                    title={item.visible ? "隐藏" : "显示"}
                    aria-label={`${item.visible ? "隐藏" : "显示"} ${item.label}`}
                    onClick={(event) => {
                      event.stopPropagation();
                      onToggleVisible(itemSelection, !item.visible);
                    }}
                  >
                    {item.visible ? <Eye size={14} /> : <EyeOff size={14} />}
                  </button>
                  <button
                    type="button"
                    disabled={kind === "camera" && composition.cameras.length <= 1}
                    title={kind === "camera" && composition.cameras.length <= 1 ? "至少保留一个机位" : "删除"}
                    aria-label={`删除 ${item.label}`}
                    onClick={(event) => {
                      event.stopPropagation();
                      onRemove(itemSelection);
                    }}
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            );
          })}
          </div>}
        </div>;
      })}
    </div>
  );
}

import { useEffect, useMemo, useReducer } from "react";
import {
  DEFAULT_COMPOSITION,
  DEFAULT_ENVIRONMENT,
  DEFAULT_JOINTS,
  defaultCamera,
  defaultCharacter,
  defaultProp,
} from "../DirectorStage.constants";
import { parseSceneSeed } from "../DirectorStage.utils";
import type {
  DirectorCamera,
  DirectorCharacter,
  DirectorComposition,
  DirectorEnvironment,
  DirectorProp,
  DirectorPropType,
  DirectorSelection,
  DirectorTransform,
  DirectorTransformMode,
  DirectorViewMode,
  JointAngles,
  ParsedSceneSeed,
} from "../DirectorStage.types";

type StageState = {
  composition: DirectorComposition;
  selection: DirectorSelection;
  transformMode: DirectorTransformMode;
  viewMode: DirectorViewMode;
  activeCameraId: string | null;
};

type Action =
  | { type: "setCameraMotions"; motions: NonNullable<DirectorComposition["cameraMotions"]> }
  | { type: "select"; selection: DirectorSelection }
  | { type: "setTransformMode"; mode: DirectorTransformMode }
  | { type: "setViewMode"; mode: DirectorViewMode; cameraId?: string | null }
  | { type: "addCharacter"; modelUrl?: string; label?: string; bodyType?: DirectorCharacter["bodyType"]; position?: DirectorCharacter["position"] }
  | { type: "addProp"; propType: DirectorPropType; label?: string; position?: DirectorProp["position"] }
  | { type: "addCamera"; camera?: Partial<DirectorCamera> }
  | { type: "removeSelected" }
  | { type: "removeItem"; selection: Exclude<DirectorSelection, null> }
  | { type: "duplicateItem"; selection: Exclude<DirectorSelection, null> }
  | { type: "setItemVisible"; selection: Exclude<DirectorSelection, null>; visible: boolean }
  | { type: "setItemLocked"; selection: Exclude<DirectorSelection, null>; locked: boolean }
  | { type: "updateCharacter"; id: string; patch: Partial<DirectorCharacter> }
  | { type: "updateProp"; id: string; patch: Partial<DirectorProp> }
  | { type: "updateCamera"; id: string; patch: Partial<DirectorCamera> }
  | { type: "transformSelected"; transform: Partial<DirectorTransform> }
  | { type: "updateEnvironment"; patch: Partial<DirectorEnvironment> }
  | { type: "importSeed"; seed: ParsedSceneSeed };

const cloneComposition = (composition: DirectorComposition): DirectorComposition => ({
  characters: composition.characters.map((item) => ({
    ...item,
    position: { ...item.position },
    rotation: { ...item.rotation },
    scale: { ...item.scale },
    jointAngles: structuredClone(item.jointAngles),
    locked: item.locked ?? false,
  })),
  props: composition.props.map((item) => ({
    ...item,
    position: { ...item.position },
    rotation: { ...item.rotation },
    scale: { ...item.scale },
    locked: item.locked ?? false,
  })),
  cameras: composition.cameras.map((item) => ({
    ...item,
    position: { ...item.position },
    lookAt: { ...item.lookAt },
    locked: item.locked ?? false,
  })),
  environment: { ...composition.environment },
});

const mergeInitialComposition = (initial?: Partial<DirectorComposition>): DirectorComposition => {
  const base = cloneComposition(DEFAULT_COMPOSITION);
  return {
    cameraMotions: initial?.cameraMotions ?? [],
    characters: initial?.characters ? initial.characters.map((item, index) => ({
      ...defaultCharacter(index),
      ...item,
      position: { ...defaultCharacter(index).position, ...item.position },
      rotation: { ...defaultCharacter(index).rotation, ...item.rotation },
      scale: { ...defaultCharacter(index).scale, ...item.scale },
      jointAngles: Object.fromEntries(Object.entries(DEFAULT_JOINTS).map(([key, value]) => [key, { ...value, ...item.jointAngles?.[key as keyof JointAngles] }])) as JointAngles,
      locked: item.locked ?? false,
    })) : base.characters,
    props: initial?.props ? initial.props.map((item, index) => ({
      ...defaultProp(index, item.propType),
      ...item,
      position: { ...defaultProp(index, item.propType).position, ...item.position },
      rotation: { ...defaultProp(index, item.propType).rotation, ...item.rotation },
      scale: { ...defaultProp(index, item.propType).scale, ...item.scale },
      locked: item.locked ?? false,
    })) : base.props,
    cameras: initial?.cameras ? initial.cameras.map((item, index) => ({
      ...defaultCamera(index),
      ...item,
      position: { ...defaultCamera(index).position, ...item.position },
      lookAt: { ...defaultCamera(index).lookAt, ...item.lookAt },
      locked: item.locked ?? false,
    })) : base.cameras,
    environment: { ...DEFAULT_ENVIRONMENT, ...initial?.environment },
  };
};

const selectAfterRemoval = (composition: DirectorComposition): DirectorSelection => {
  if (composition.cameras[0]) return { kind: "camera", id: composition.cameras[0].id };
  if (composition.characters[0]) return { kind: "character", id: composition.characters[0].id };
  if (composition.props[0]) return { kind: "prop", id: composition.props[0].id };
  return null;
};

export function directorStageReducer(state: StageState, action: Action): StageState {
  switch (action.type) {
    case "setCameraMotions": return { ...state, composition: { ...state.composition, cameraMotions: action.motions } };
    case "select":
      return {
        ...state,
        selection: action.selection,
        activeCameraId: action.selection?.kind === "camera" ? action.selection.id : state.activeCameraId,
      };
    case "setTransformMode":
      return { ...state, transformMode: action.mode };
    case "setViewMode":
      return {
        ...state,
        viewMode: action.mode,
        activeCameraId: action.cameraId ?? (state.activeCameraId ?? state.composition.cameras[0]?.id ?? null),
      };
    case "addCharacter": {
      const next = {
        ...defaultCharacter(state.composition.characters.length),
        ...(action.modelUrl ? { bodyType: "custom" as const, modelUrl: action.modelUrl, animationMode: "static" as const } : {}),
        ...(action.bodyType ? { bodyType: action.bodyType } : {}),
        ...(action.label ? { label: action.label } : {}),
        ...(action.position ? { position: action.position } : {}),
      };
      return {
        ...state,
        composition: { ...state.composition, characters: [...state.composition.characters, next] },
        selection: { kind: "character", id: next.id },
      };
    }
    case "addProp": {
      const next = {
        ...defaultProp(state.composition.props.length, action.propType),
        ...(action.label ? { label: action.label } : {}),
        ...(action.position ? { position: action.position } : {}),
      };
      return {
        ...state,
        composition: { ...state.composition, props: [...state.composition.props, next] },
        selection: { kind: "prop", id: next.id },
      };
    }
    case "addCamera": {
      const next = {
        ...defaultCamera(state.composition.cameras.length),
        ...action.camera,
        position: { ...defaultCamera(state.composition.cameras.length).position, ...action.camera?.position },
        lookAt: { ...defaultCamera(state.composition.cameras.length).lookAt, ...action.camera?.lookAt },
      };
      return {
        ...state,
        composition: { ...state.composition, cameras: [...state.composition.cameras, next] },
        selection: { kind: "camera", id: next.id },
        activeCameraId: next.id,
      };
    }
    case "removeSelected": {
      if (!state.selection) return state;
      return directorStageReducer(state, { type: "removeItem", selection: state.selection });
    }
    case "removeItem": {
      if (action.selection.kind === "camera" && state.composition.cameras.length <= 1) return state;
      const composition = {
        ...state.composition,
        cameraMotions: state.composition.cameraMotions?.filter((motion) => motion.cameraId !== action.selection.id),
        characters: action.selection.kind === "character"
          ? state.composition.characters.filter((item) => item.id !== action.selection.id)
          : state.composition.characters,
        props: action.selection.kind === "prop"
          ? state.composition.props.filter((item) => item.id !== action.selection.id)
          : state.composition.props,
        cameras: action.selection.kind === "camera"
          ? state.composition.cameras.filter((item) => item.id !== action.selection.id)
          : state.composition.cameras,
      };
      const removedSelected = state.selection?.kind === action.selection.kind && state.selection.id === action.selection.id;
      return {
        ...state,
        composition,
        selection: removedSelected ? selectAfterRemoval(composition) : state.selection,
        activeCameraId: composition.cameras.some((camera) => camera.id === state.activeCameraId)
          ? state.activeCameraId
          : composition.cameras[0]?.id ?? null,
      };
    }
    case "duplicateItem": {
      if (action.selection.kind === "character") {
        const source = state.composition.characters.find((item) => item.id === action.selection.id);
        if (!source) return state;
        const next: DirectorCharacter = {
          ...source,
          id: `character-${crypto.randomUUID()}`,
          label: `${source.label} Copy`,
          position: { ...source.position, x: source.position.x + 0.45, z: source.position.z + 0.35 },
          rotation: { ...source.rotation },
          scale: { ...source.scale },
          jointAngles: structuredClone(source.jointAngles),
          locked: false,
        };
        return {
          ...state,
          composition: { ...state.composition, characters: [...state.composition.characters, next] },
          selection: { kind: "character", id: next.id },
        };
      }
      if (action.selection.kind === "prop") {
        const source = state.composition.props.find((item) => item.id === action.selection.id);
        if (!source) return state;
        const next: DirectorProp = {
          ...source,
          id: `prop-${crypto.randomUUID()}`,
          label: `${source.label} Copy`,
          position: { ...source.position, x: source.position.x + 0.45, z: source.position.z + 0.35 },
          rotation: { ...source.rotation },
          scale: { ...source.scale },
          locked: false,
        };
        return {
          ...state,
          composition: { ...state.composition, props: [...state.composition.props, next] },
          selection: { kind: "prop", id: next.id },
        };
      }
      const source = state.composition.cameras.find((item) => item.id === action.selection.id);
      if (!source) return state;
      const next: DirectorCamera = {
        ...source,
        id: `camera-${crypto.randomUUID()}`,
        label: `${source.label} Copy`,
        position: { ...source.position, x: source.position.x + 0.45, z: source.position.z + 0.35 },
        lookAt: { ...source.lookAt },
        locked: false,
      };
      return {
        ...state,
        composition: { ...state.composition, cameras: [...state.composition.cameras, next] },
        selection: { kind: "camera", id: next.id },
        activeCameraId: next.id,
      };
    }
    case "setItemVisible": {
      if (action.selection.kind === "character") {
        return directorStageReducer(state, { type: "updateCharacter", id: action.selection.id, patch: { visible: action.visible } });
      }
      if (action.selection.kind === "prop") {
        return directorStageReducer(state, { type: "updateProp", id: action.selection.id, patch: { visible: action.visible } });
      }
      return directorStageReducer(state, { type: "updateCamera", id: action.selection.id, patch: { visible: action.visible } });
    }
    case "setItemLocked": {
      if (action.selection.kind === "character") {
        return directorStageReducer(state, { type: "updateCharacter", id: action.selection.id, patch: { locked: action.locked } });
      }
      if (action.selection.kind === "prop") {
        return directorStageReducer(state, { type: "updateProp", id: action.selection.id, patch: { locked: action.locked } });
      }
      return directorStageReducer(state, { type: "updateCamera", id: action.selection.id, patch: { locked: action.locked } });
    }
    case "updateCharacter":
      return {
        ...state,
        composition: {
          ...state.composition,
          characters: state.composition.characters.map((item) => item.id === action.id ? { ...item, ...action.patch } : item),
        },
      };
    case "updateProp":
      return {
        ...state,
        composition: {
          ...state.composition,
          props: state.composition.props.map((item) => item.id === action.id ? { ...item, ...action.patch } : item),
        },
      };
    case "updateCamera":
      return {
        ...state,
        composition: {
          ...state.composition,
          cameras: state.composition.cameras.map((item) => item.id === action.id ? { ...item, ...action.patch } : item),
        },
      };
    case "transformSelected": {
      if (!state.selection) return state;
      if (state.selection.kind === "character") {
        const current = state.composition.characters.find((item) => item.id === state.selection?.id);
        if (current?.locked) return state;
        return directorStageReducer(state, { type: "updateCharacter", id: state.selection.id, patch: action.transform });
      }
      if (state.selection.kind === "prop") {
        const current = state.composition.props.find((item) => item.id === state.selection?.id);
        if (current?.locked) return state;
        return directorStageReducer(state, { type: "updateProp", id: state.selection.id, patch: action.transform });
      }
      const current = state.composition.cameras.find((item) => item.id === state.selection?.id);
      if (current?.locked) return state;
      return directorStageReducer(state, {
        type: "updateCamera",
        id: state.selection.id,
        patch: action.transform.position ? { position: action.transform.position } : {},
      });
    }
    case "updateEnvironment":
      return {
        ...state,
        composition: {
          ...state.composition,
          environment: { ...state.composition.environment, ...action.patch },
        },
      };
    case "importSeed": {
      const characters = action.seed.characters?.map((item, index) => ({
        ...defaultCharacter(index),
        ...item,
        id: `character-${crypto.randomUUID()}`,
        position: { ...defaultCharacter(index).position, ...item.position },
        rotation: { ...defaultCharacter(index).rotation, ...item.rotation },
        scale: { ...defaultCharacter(index).scale, ...item.scale },
        jointAngles: Object.fromEntries(Object.entries(DEFAULT_JOINTS).map(([key, value]) => [key, { ...value, ...item.jointAngles?.[key as keyof JointAngles] }])) as JointAngles,
        locked: item.locked ?? false,
      })) ?? state.composition.characters;
      const props = action.seed.props?.map((item, index) => ({
        ...defaultProp(index, item.propType),
        ...item,
        id: `prop-${crypto.randomUUID()}`,
        position: { ...defaultProp(index, item.propType).position, ...item.position },
        rotation: { ...defaultProp(index, item.propType).rotation, ...item.rotation },
        scale: { ...defaultProp(index, item.propType).scale, ...item.scale },
        locked: item.locked ?? false,
      })) ?? state.composition.props;
      const cameras = action.seed.cameras?.map((item, index) => ({
        ...defaultCamera(index),
        ...item,
        id: `camera-${crypto.randomUUID()}`,
        position: { ...defaultCamera(index).position, ...item.position },
        lookAt: { ...defaultCamera(index).lookAt, ...item.lookAt },
        locked: item.locked ?? false,
      })) ?? state.composition.cameras;
      const composition = {
        ...state.composition,
        cameraMotions: (action.seed.cameraMotions ?? []).flatMap((motion) => {
          const sourceIndex = action.seed.cameras?.findIndex((camera) => camera.id === motion.cameraId) ?? -1;
          const camera = sourceIndex >= 0 ? cameras[sourceIndex] : cameras.find((camera) => camera.id === motion.cameraId);
          return camera ? [{ ...motion, cameraId: camera.id, camera: { ...motion.camera, id: camera.id } }] : [];
        }),
        characters,
        props,
        cameras,
        environment: { ...state.composition.environment, ...action.seed.environment },
      };
      return {
        ...state,
        composition,
        selection: selectAfterRemoval(composition),
        activeCameraId: cameras[0]?.id ?? null,
      };
    }
    default:
      return state;
  }
}

export function useDirectorStage(initial?: Partial<DirectorComposition>, storageKey?: string | false) {
  const initializer = () => {
    const fallback = mergeInitialComposition(initial);
    if (!storageKey || typeof window === "undefined") {
      return fallback;
    }
    try {
      const stored = window.localStorage.getItem(storageKey);
      if (stored) {
        return mergeInitialComposition(parseSceneSeed(stored) as Partial<DirectorComposition>);
      }
    } catch {
      // Ignore corrupt local drafts and rebuild from defaults.
    }
    return fallback;
  };

  const [state, dispatch] = useReducer(directorStageReducer, undefined, () => {
    const composition = initializer();
    return {
      composition,
      selection: selectAfterRemoval(composition),
      transformMode: "translate" as DirectorTransformMode,
      viewMode: "director" as DirectorViewMode,
      activeCameraId: composition.cameras[0]?.id ?? null,
    };
  });

  useEffect(() => {
    if (!storageKey || typeof window === "undefined") return;
    try { window.localStorage.setItem(storageKey, JSON.stringify(state.composition)); } catch { /* Storage may be disabled or full. Keep the editor usable. */ }
  }, [state.composition, storageKey]);

  const selected = useMemo(() => {
    if (!state.selection) return null;
    if (state.selection.kind === "character") {
      return state.composition.characters.find((item) => item.id === state.selection?.id) ?? null;
    }
    if (state.selection.kind === "prop") {
      return state.composition.props.find((item) => item.id === state.selection?.id) ?? null;
    }
    return state.composition.cameras.find((item) => item.id === state.selection?.id) ?? null;
  }, [state.composition, state.selection]);

  return { state, selected, dispatch };
}

