import { TransformControls } from "@react-three/drei";
import React, { useState } from "react";
import * as THREE from "three";
import type { DirectorTransform, DirectorTransformMode, Vector3Like } from "../DirectorStage.types";

type TransformableProps = {
  selected: boolean;
  mode: DirectorTransformMode;
  transform: DirectorTransform;
  children: React.ReactNode;
  onSelect: () => void;
  onTransform: (transform: Partial<DirectorTransform>) => void;
  onDragChange?: (dragging: boolean) => void;
};

const toVector = (value: Vector3Like) => [value.x, value.y, value.z] as [number, number, number];
const toRotation = (value: Vector3Like) => [value.x * Math.PI / 180, value.y * Math.PI / 180, value.z * Math.PI / 180] as [number, number, number];
const fromVector = (value: THREE.Vector3): Vector3Like => ({ x: value.x, y: value.y, z: value.z });
const fromEuler = (value: THREE.Euler): Vector3Like => ({
  x: value.x * 180 / Math.PI,
  y: value.y * 180 / Math.PI,
  z: value.z * 180 / Math.PI,
});

export default function Transformable({
  selected,
  mode,
  transform,
  children,
  onSelect,
  onTransform,
  onDragChange,
}: TransformableProps) {
  const [object, setObject] = useState<THREE.Group | null>(null);

  const emitTransform = () => {
    if (!object) return;
    onTransform({
      position: fromVector(object.position),
      rotation: fromEuler(object.rotation),
      scale: fromVector(object.scale),
    });
  };

  const group = (
    <group
      ref={setObject}
      position={toVector(transform.position)}
      rotation={toRotation(transform.rotation)}
      scale={toVector(transform.scale)}
      onPointerDown={(event) => {
        event.stopPropagation();
        onSelect();
      }}
    >
      {children}
    </group>
  );

  return (
    <>
      {group}
      {selected && object ? (
        <TransformControls
          object={object}
          mode={mode}
          space="world"
          size={0.78}
          onObjectChange={emitTransform}
          onMouseDown={() => onDragChange?.(true)}
          onMouseUp={() => {
            onDragChange?.(false);
            emitTransform();
          }}
        />
      ) : null}
    </>
  );
}

export type CameraWirePoint = [number, number, number];

export type CameraWireLine = {
  part: "body" | "lens" | "reel";
  points: CameraWirePoint[];
};

const CAMERA_HIT_PADDING = 0.06;
const CAMERA_ASPECT = 16 / 9;
const CAMERA_FRUSTUM_DEPTH = 1.72;
const CAMERA_FRUSTUM_FRAME_WIDTH = 1.08;
const CAMERA_BODY_CENTER: CameraWirePoint = [0, 0, -0.18];
const CAMERA_BODY_SIZE: CameraWirePoint = [0.52, 0.66, 0.56];
const CAMERA_BODY_FRONT_Z = CAMERA_BODY_CENTER[2] + CAMERA_BODY_SIZE[2] / 2;
const CAMERA_LENS_TIP: CameraWirePoint = [0, 0, 0.32];

function createBoxLines(
  center: CameraWirePoint,
  size: CameraWirePoint,
): CameraWirePoint[][] {
  const [cx, cy, cz] = center;
  const [width, height, depth] = size;
  const x0 = cx - width / 2;
  const x1 = cx + width / 2;
  const y0 = cy - height / 2;
  const y1 = cy + height / 2;
  const z0 = cz - depth / 2;
  const z1 = cz + depth / 2;
  const corners = {
    bbl: [x0, y0, z0] as CameraWirePoint,
    bbr: [x1, y0, z0] as CameraWirePoint,
    btl: [x0, y1, z0] as CameraWirePoint,
    btr: [x1, y1, z0] as CameraWirePoint,
    fbl: [x0, y0, z1] as CameraWirePoint,
    fbr: [x1, y0, z1] as CameraWirePoint,
    ftl: [x0, y1, z1] as CameraWirePoint,
    ftr: [x1, y1, z1] as CameraWirePoint,
  };

  return [
    [corners.bbl, corners.bbr, corners.btr, corners.btl, corners.bbl],
    [corners.fbl, corners.fbr, corners.ftr, corners.ftl, corners.fbl],
    [corners.bbl, corners.fbl],
    [corners.bbr, corners.fbr],
    [corners.btr, corners.ftr],
    [corners.btl, corners.ftl],
  ];
}

function createLensLines(): CameraWirePoint[][] {
  const back: CameraWirePoint[] = [
    [-0.1, 0.1, CAMERA_BODY_FRONT_Z],
    [0.1, 0.1, CAMERA_BODY_FRONT_Z],
    [0.1, -0.1, CAMERA_BODY_FRONT_Z],
    [-0.1, -0.1, CAMERA_BODY_FRONT_Z],
  ];
  const front: CameraWirePoint[] = [
    [-0.13, 0.13, CAMERA_LENS_TIP[2]],
    [0.13, 0.13, CAMERA_LENS_TIP[2]],
    [0.13, -0.13, CAMERA_LENS_TIP[2]],
    [-0.13, -0.13, CAMERA_LENS_TIP[2]],
  ];

  return [
    [...back, back[0]],
    [...front, front[0]],
    ...back.map((point, index) => [point, front[index]]),
  ];
}

function createReelLine(centerZ: number): CameraWirePoint[] {
  const segments = 32;
  const radius = 0.1;
  const centerY = 0.18;

  return Array.from({ length: segments + 1 }, (_, index) => {
    const angle = (Math.PI * 2 * index) / segments;
    return [
      0,
      centerY + Math.cos(angle) * radius,
      centerZ + Math.sin(angle) * radius,
    ];
  });
}

export function getCameraBodyLines(): CameraWireLine[] {
  return [
    ...createBoxLines(CAMERA_BODY_CENTER, CAMERA_BODY_SIZE).map((points) => ({
      part: "body" as const,
      points,
    })),
    ...createLensLines().map((points) => ({
      part: "lens" as const,
      points,
    })),
    {
      part: "reel",
      points: createReelLine(-0.3),
    },
    {
      part: "reel",
      points: createReelLine(-0.08),
    },
  ];
}

export function getCameraFrustumLines(): CameraWirePoint[][] {
  const halfWidth = CAMERA_FRUSTUM_FRAME_WIDTH / 2;
  const halfHeight = CAMERA_FRUSTUM_FRAME_WIDTH / CAMERA_ASPECT / 2;
  const corners: CameraWirePoint[] = [
    [-halfWidth, halfHeight, CAMERA_FRUSTUM_DEPTH],
    [halfWidth, halfHeight, CAMERA_FRUSTUM_DEPTH],
    [halfWidth, -halfHeight, CAMERA_FRUSTUM_DEPTH],
    [-halfWidth, -halfHeight, CAMERA_FRUSTUM_DEPTH],
  ];

  return [
    ...corners.map((corner) => [CAMERA_LENS_TIP, corner]),
    [corners[0], corners[1], corners[2], corners[3], corners[0]],
  ];
}

export function getCameraHitArea() {
  const points = getCameraBodyLines().flatMap((line) => line.points);
  const xs = points.map((point) => point[0]);
  const ys = points.map((point) => point[1]);
  const zs = points.map((point) => point[2]);
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);
  const minZ = Math.min(...zs);
  const maxZ = Math.max(...zs);

  return {
    args: [
      maxX - minX + CAMERA_HIT_PADDING * 2,
      maxY - minY + CAMERA_HIT_PADDING * 2,
      maxZ - minZ + CAMERA_HIT_PADDING * 2,
    ] as CameraWirePoint,
    position: [
      (minX + maxX) / 2,
      (minY + maxY) / 2,
      (minZ + maxZ) / 2,
    ] as CameraWirePoint,
  };
}

type DirectorVector3 = [number, number, number];

export type DirectorCameraMotionPresetId =
  | "orbit"
  | "arc"
  | "dolly-in"
  | "dolly-out"
  | "dolly-zoom"
  | "crane-up"
  | "crane-down"
  | "truck"
  | "spiral";

export type DirectorCameraMotionPreset = {
  id: DirectorCameraMotionPresetId;
  label: string;
  description: string;
};

export const DIRECTOR_CAMERA_MOTION_PRESETS: DirectorCameraMotionPreset[] = [
  { id: "orbit", label: "环绕", description: "围绕主体完成一圈运动" },
  { id: "arc", label: "半弧", description: "围绕主体移动半圈" },
  { id: "dolly-in", label: "推近", description: "沿视线靠近主体" },
  { id: "dolly-out", label: "拉远", description: "沿视线远离主体" },
  { id: "dolly-zoom", label: "滑动变焦", description: "推近同时改变焦距" },
  { id: "crane-up", label: "上升", description: "镜头垂直升高" },
  { id: "crane-down", label: "下降", description: "镜头垂直降低" },
  { id: "truck", label: "横移", description: "镜头水平横向移动" },
  { id: "spiral", label: "螺旋", description: "环绕主体并持续上升" },
];

function round(point: DirectorVector3): DirectorVector3 {
  return point.map((value) => Number(value.toFixed(4))) as DirectorVector3;
}

export function createDirectorCameraPresetPositions(
  presetId: DirectorCameraMotionPresetId,
  camera: DirectorVector3,
  center: DirectorVector3,
): DirectorVector3[] {
  const dx = camera[0] - center[0];
  const dz = camera[2] - center[2];
  const radius = Math.max(2, Math.hypot(dx, dz));
  const startAngle = Math.atan2(dz, dx);
  const y = camera[1];

  if (presetId === "orbit" || presetId === "arc" || presetId === "spiral") {
    const span = presetId === "arc" ? Math.PI : Math.PI * 2;
    const count = presetId === "arc" ? 5 : 9;
    return Array.from({ length: count }, (_, index) => {
      const ratio = index / (count - 1);
      const angle = startAngle + span * ratio;
      const height = presetId === "spiral" ? y + ratio * 5 : y;
      return round([
        center[0] + Math.cos(angle) * radius,
        height,
        center[2] + Math.sin(angle) * radius,
      ]);
    });
  }

  const towardCenter: DirectorVector3 = [
    center[0] - camera[0],
    center[1] + 1.2 - camera[1],
    center[2] - camera[2],
  ];
  const length = Math.hypot(...towardCenter) || 1;
  const forward = towardCenter.map(
    (value) => value / length,
  ) as DirectorVector3;
  const endpoint = (distance: number): DirectorVector3 =>
    round(
      camera.map(
        (value, index) => value + forward[index] * distance,
      ) as DirectorVector3,
    );

  if (presetId === "dolly-in" || presetId === "dolly-zoom") {
    return [camera, endpoint(Math.max(2, radius * 0.62))];
  }
  if (presetId === "dolly-out")
    return [camera, endpoint(-Math.max(3, radius * 0.65))];
  if (presetId === "crane-up")
    return [camera, round([camera[0], camera[1] + 5, camera[2]])];
  if (presetId === "crane-down") {
    return [
      camera,
      round([camera[0], Math.max(0.8, camera[1] - 4), camera[2]]),
    ];
  }
  const right: DirectorVector3 = [forward[2], 0, -forward[0]];
  return [
    round(
      camera.map((value, index) => value - right[index] * 4) as DirectorVector3,
    ),
    round(
      camera.map((value, index) => value + right[index] * 4) as DirectorVector3,
    ),
  ];
}

import { CatmullRomCurve3, Vector3 } from "three";
import type { DirectorCamera, DirectorCameraMotion } from "./DirectorStage.types";

export function sampleCameraMotion(motion: DirectorCameraMotion, time: number): DirectorCamera {
  const t = Math.max(0, Math.min(1, (time - motion.start) / motion.duration));
  const points = motion.points.map((point) => new Vector3(...point));
  const position = points.length === 2 ? points[0].clone().lerp(points[1], t) : new CatmullRomCurve3(points, false, "centripetal").getPoint(t);
  const { camera } = motion;
  const target = new Vector3(camera.lookAt.x, camera.lookAt.y, camera.lookAt.z);
  const originalDistance = new Vector3(camera.position.x, camera.position.y, camera.position.z).distanceTo(target);
  const fov = motion.preset === "dolly-zoom" ? 2 * Math.atan(Math.tan(camera.fov * Math.PI / 360) * originalDistance / Math.max(0.1, position.distanceTo(target))) * 180 / Math.PI : camera.fov;
  return { ...camera, id: motion.cameraId, position: { x: position.x, y: position.y, z: position.z }, fov: Math.max(5, Math.min(150, fov)) };
}

import { useState } from "react";
import { Download, Pause, Play, Plus, Route, Trash2, X } from "lucide-react";
import { createDirectorCameraPresetPositions, DIRECTOR_CAMERA_MOTION_PRESETS, type DirectorCameraMotionPresetId } from "./camera-motion-presets";
import type { DirectorCamera, DirectorCameraMotion } from "./DirectorStage.types";

type Props = {
  cameras: DirectorCamera[];
  activeCameraId: string | null;
  motions: DirectorCameraMotion[];
  time: number;
  playing: boolean;
  onTime: (time: number) => void;
  onPlaying: (playing: boolean) => void;
  onChange: (motions: DirectorCameraMotion[]) => void;
  onClose: () => void;
  onExport: () => void;
};

export default function DirectorTimeline({ cameras, activeCameraId, motions, time, playing, onTime, onPlaying, onChange, onClose, onExport }: Props) {
  const [picker, setPicker] = useState(false);
  const [selected, setSelected] = useState<string | null>(null);
  const [zoom, setZoom] = useState(60);
  const duration = Math.max(6, ...motions.map((motion) => motion.start + motion.duration));
  const selection = motions.find((motion) => motion.id === selected);
  const addPath = (preset: DirectorCameraMotionPresetId) => {
    const camera = cameras.find((item) => item.id === activeCameraId) ?? cameras[0];
    if (!camera) return;
    const lastEnd = Math.max(0, ...motions.map((motion) => motion.start + motion.duration));
    const points = createDirectorCameraPresetPositions(preset, [camera.position.x, camera.position.y, camera.position.z], [camera.lookAt.x, 0, camera.lookAt.z]);
    const next: DirectorCameraMotion = { id: crypto.randomUUID(), cameraId: camera.id, camera: structuredClone(camera), label: DIRECTOR_CAMERA_MOTION_PRESETS.find((item) => item.id === preset)!.label, preset, points, duration: 6, start: lastEnd };
    onChange([...motions, next]); setSelected(next.id); setPicker(false); onPlaying(false); onTime(next.start);
  };
  return <section className="director-stage__timeline" aria-label="运镜时间线">
    <header>
      <button type="button" aria-label={playing ? "暂停时间轴" : "播放时间轴"} disabled={!motions.length} onClick={() => { if (time >= duration) onTime(0); onPlaying(!playing); }}>{playing ? <Pause size={16} /> : <Play size={16} />}</button>
      <output>{time.toFixed(1)}s / {duration.toFixed(1)}s</output>
      <button type="button" className="is-primary" disabled={!cameras.length} onClick={() => setPicker(!picker)}><Plus size={14} />添加路径</button>
      <button type="button" aria-label="删除选中路径" disabled={!selection} onClick={() => { onPlaying(false); onChange(motions.filter((motion) => motion.id !== selected)); setSelected(null); }}><Trash2 size={14} /></button>
      {selection && <label>时长<input type="number" min={0.5} max={120} step={0.5} value={selection.duration} onChange={(event) => { const value = Number(event.target.value); if (value >= 0.5 && value <= 120) { onPlaying(false); onChange(motions.map((motion) => motion.id === selected ? { ...motion, duration: value } : motion)); } }} />秒</label>}
      <button type="button" disabled={!motions.length} onClick={onExport}><Download size={14} />导出视频</button>
      <label className="director-stage__timeline-zoom">缩放<input aria-label="时间线缩放" type="range" min={30} max={120} value={zoom} onChange={(event) => setZoom(Number(event.target.value))} /></label>
      <button type="button" aria-label="关闭时间轴" onClick={onClose}><X size={16} /></button>
    </header>
    {picker && <div className="director-stage__path-picker">{DIRECTOR_CAMERA_MOTION_PRESETS.map((preset) => <button type="button" key={preset.id} onClick={() => addPath(preset.id)}><Route size={16} /><span>{preset.label}<small>{preset.description}</small></span></button>)}</div>}
    <div className="director-stage__timeline-scroll">
      <div style={{ minWidth: Math.max(500, duration * zoom + 150) }}>
        <div className="director-stage__time-ruler"><span>机位轨道</span><input aria-label="时间轴播放位置" type="range" min={0} max={duration} step={0.01} value={Math.min(time, duration)} onChange={(event) => { onPlaying(false); onTime(Number(event.target.value)); }} /></div>
        {cameras.map((camera) => <div className="director-stage__track" key={camera.id}><span>{camera.label}</span><div className="director-stage__track-lane">{motions.filter((motion) => motion.cameraId === camera.id).map((motion) => <button type="button" key={motion.id} className={selected === motion.id ? "is-selected" : ""} style={{ left: `${motion.start / duration * 100}%`, width: `${motion.duration / duration * 100}%` }} onClick={() => { setSelected(motion.id); onPlaying(false); onTime(motion.start); }}>{motion.label} · {motion.duration}s</button>)}<i style={{ left: `${Math.min(time / duration, 1) * 100}%` }} /></div></div>)}
        {!motions.length && <p className="director-stage__timeline-empty">为当前机位添加运镜路径，播放或拖动时间轴预览。</p>}
      </div>
    </div>
  </section>;
}

import type { DirectorBodyType as DirectorCharacterBodyType } from "./DirectorStage.types";
type Ue4BoneScaleMap = Record<string, [number, number, number]>;
