export function getUe4ModelScale(
  bodyType?: DirectorCharacterBodyType,
): [number, number, number] {
  switch (bodyType) {
    case "teen":
      return [0.88, 0.88, 0.88];
    case "child":
      return [0.72, 0.72, 0.72];
    case "chibi":
      return [0.56, 0.56, 0.56];
    default:
      return [1, 1, 1];
  }
}

